-- SSH private keys (§3.1, §23.2). The uuid is generated by the application
-- so the envelope AAD (table || column || uuid) can bind the ciphertext to
-- its row at insert time (data-dictionary §2.7).

-- name: CreatePrivateKey :one
INSERT INTO private_keys (uuid, team_id, name, description, fingerprint_sha256, public_key, private_key_enc, is_instance)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
RETURNING *;

-- name: GetPrivateKeyByUUID :one
SELECT * FROM private_keys WHERE uuid = $1 AND team_id = $2;

-- name: GetInstancePrivateKey :one
SELECT * FROM private_keys WHERE is_instance;

-- name: GetPrivateKeyByID :one
SELECT * FROM private_keys WHERE id = $1;

-- name: ListPrivateKeysPage :many
SELECT * FROM private_keys
WHERE team_id = sqlc.arg(team_id)
  AND (sqlc.arg(after_id)::bigint = 0 OR id < sqlc.arg(after_id))
ORDER BY id DESC
LIMIT sqlc.arg(page_limit);

-- name: UpdatePrivateKey :execrows
UPDATE private_keys
SET name = $2, description = $3, fingerprint_sha256 = $4, public_key = $5,
    private_key_enc = $6, updated_at = now(), version = version + 1
WHERE id = $1 AND version = sqlc.arg(expected_version);

-- name: DeletePrivateKey :execrows
DELETE FROM private_keys WHERE id = $1;
